def _som_construct(*args: object, **kwargs: object) -> None:
    """Set mapped values; the row is positional so any field name works."""
    (row,) = args
    kind = type(row)
    for key, value in kwargs.items():
        if not hasattr(kind, key):
            message = f"{key!r} is an invalid keyword argument for {kind.__name__}"
            raise TypeError(message)
        setattr(row, key, value)


