def encode_date(value: date) -> datetime:


    """Encode date."""
    if isinstance(value, datetime):
        return value
    return datetime.combine(value, time(), UTC)


def _som_query_indexes(fields: list[str | None], prefix: list[str]) -> list[list[str]]:


